window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d850fa0129218c46"]={"versions": [{"id": "FIG-d850fa0129218c46", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm zur Spezifikation des AUTOSAR BSW-Konfigurationsmetamodells (ECUC Parameter Definition Metamodel gemäß AUTOSAR Generic Structure Template).</li>\n<li><strong>Technischer Zweck:</strong> Definition der Konfigurationsstruktur des BSW-Moduls <code>SwCluC</code> (<em>Software Cluster Connection</em>, eingeführt in AUTOSAR Classic Platform R20-11) zur Steuerung der Codegenerierung von Inter-Cluster-Proxies für Kern-BSW-Dienste (<em>Operating System</em> und <em>Non-Volatile Memory Manager</em>).</li>\n<li><strong>Funktionale Einordnung:</strong> Ermöglicht die Entkopplung und asymmetrische Verteilung von Software-Clustern (SWCLs) auf einer ECU (z. B. Host-Cluster mit Basistreiber-/BSW-Instanzen vs. separat updatebare Applikations-Cluster). Die Konfiguration legt fest, ob ein Software-Cluster als Service-Konsument (Client), Service-Bereitsteller (Server) oder autark agiert.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>SwCluC</code> (<code>EcucModuleDef</code>):</strong></li>\n<li>Wurzelelement der Modulkonfigurationsdefinition des Software-Cluster-Connection-Moduls.</li>\n<li><em>Multiplizität:</em> <code>[0..1]</code> (kann je ECU-Konfiguration maximal einmal instanziiert werden; Namensraum <code>(from SwCluC)</code>).</li>\n<li><strong><code>SwCluCProxies</code> (<code>EcucParamConfContainerDef</code>):</strong></li>\n<li>Zentraler Konfigurationscontainer für generelle Proxy-Generierungsparameter.</li>\n<li><em>Beziehung:</em> Komposition (<code>+container</code>, gefüllte Raute) von <code>SwCluC</code> mit strikter Kardinalität <code>[1..1]</code> (Pflichtcontainer).</li>\n<li><strong><code>SwCluCProxyGenerationOs</code> (<code>EcucEnumerationParamDef</code>):</strong></li>\n<li>Steuerungsparameter für OS-Proxy-Artefakte.</li>\n<li><em>Beziehung:</em> Komposition (<code>+parameter</code>) unter <code>SwCluCProxies</code> mit Kardinalität <code>[1..1]</code>.</li>\n<li><em>Literale (<code>EcucEnumerationLiteralDef</code> via <code>+literal</code>, jeweils [0..1] Auswahl):</em></li>\n<li><code>PROXY_DISABLED</code>: Keine Generierung von OS-Proxies im Ziel-Cluster (Cluster nutzt OS direkt lokal oder benötigt keine OS-Dienste über SwCluC).</li>\n<li><code>HIGH_PROXY</code>: Generiert den aufrufenden OS-Proxy (Client-/Caller-Seite) im abhängigen Cluster; fängt OS-Service-Calls ab und leitet sie über den SwCluC-Transport weiter.</li>\n<li><code>LOW_PROXY</code>: Generiert den empfangenden OS-Proxy (Server-/Dispatcher-Seite) im Host-Cluster; nimmt weitergeleitete OS-Calls entgegen und ruft die eigentliche OS-Implementierung auf.</li>\n<li><strong><code>SwCluCProxyGenerationNvM</code> (<code>EcucEnumerationParamDef</code>):</strong></li>\n<li>Steuerungsparameter für NvM-Proxy-Artefakte.</li>\n<li><em>Beziehung:</em> Komposition (<code>+parameter</code>) unter <code>SwCluCProxies</code> mit Kardinalität <code>[1..1]</code>.</li>\n<li><em>Literale (<code>EcucEnumerationLiteralDef</code> via <code>+literal</code>, jeweils [0..1] Auswahl):</em></li>\n<li><code>PROXY_DISABLED</code>: Keine NvM-Proxy-Generierung.</li>\n<li><code>HIGH_PROXY</code>: Generiert den Client-Proxy für NvM-Dienste (z. B. <code>NvM_ReadBlock</code>, <code>NvM_WriteBlock</code>) im Konsumenten-Cluster inklusive IPC-Serialisierung.</li>\n<li><code>LOW_PROXY</code>: Generiert den Dispatcher-Proxy im Host-Cluster, welcher Anfragen an den nativen NvM-Stack durchstellt und Rückmelde-Callbacks handhabt.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (Generierungs- und Interaktionspfad)</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell handelt, bestimmt die Konfiguration den Codegenerator-Pfad sowie den resultierenden Laufzeit-Interaktionsfluss:</p>\n<ol class=\"fig-list\">\n<li><strong>Generierungsphase (Pre-Compile / Build Time):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ist im Cluster A <code>HIGH_PROXY</code> und im Cluster B <code>LOW_PROXY</code> für ein Modul (z. B. NvM) konfiguriert, erzeugt das SwCluC-Generatortool für Cluster A die API-Header/Stubs (<code>High Proxy</code>) und für Cluster B die Dispatcher-Funktionen (<code>Low Proxy</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchroner Request-Pfad (Laufzeit):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>SWC in Cluster A ruft Standard-API auf (z. B. <code>NvM_WriteBlock(...)</code>).</li>\n<li><code>HIGH_PROXY</code> fängt Aufruf ab, serialisiert Argumente (Block-ID, Pufferzeiger/Payload) in ein Inter-Cluster-Nachrichtenformat und triggert den SwCluC-Transport (z. B. Shared Memory, Mailbox-IPC oder Hardware-IPC).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Dispatcher & BSW-Ausführung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>SwCluC-Stack in Cluster B signalisiert Datenverfügbarkeit; <code>LOW_PROXY</code> deserialisiert die Daten und ruft die native BSW-Funktion (<code>NvM_WriteBlock</code>) im lokalen Kontext des Host-Clusters auf.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Asynchrone Callbacks & Job-Terminierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei Abschluss des NvM-Jobs triggert der native Stack den Callback im Host-Cluster.</li>\n<li>Der <code>LOW_PROXY</code> übermittelt den Status (<code>NVM_REQ_OK</code>, <code>NVM_REQ_NOT_OK</code>) über SwCluC zurück an Cluster A, wo der <code>HIGH_PROXY</code> den registrierten Single-Block-/Multi-Block-Callback der anfordernden SWC ausführt.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationskonsistenz (ECUC_SwCluC_00036):</strong></li>\n<li>Die Konfiguration muss clusterübergreifend komplementär sein: Konfiguriert ein Applikations-Cluster <code>HIGH_PROXY</code>, <em>muss</em> der bereitstellende Host-Cluster zwingend auf <code>LOW_PROXY</code> für dasselbe Modul parametriert sein. Eine Fehlkonfiguration (<code>HIGH_PROXY</code> ohne korrespondierenden <code>LOW_PROXY</code> oder beidseitig <code>LOW_PROXY</code>) führt zu unaufgelösten Symbolen beim Linken oder deadlocks im IPC-Handshake.</li>\n<li><strong>API-Transparenz für Applikations-Entwickler:</strong></li>\n<li>Durch <code>HIGH_PROXY</code> bleibt die Standard-AUTOSAR-Schnittstelle (<code>Os.h</code>, <code>NvM.h</code>) für SWCs und CDDs im Applikations-Cluster identisch. Es ist keine Anpassung des SWC-Codes erforderlich; die Umleitung auf SwCluC geschieht rein über Include-Pfade und Linker-Reihenfolge.</li>\n<li><strong>Timing & Latenzen:</strong></li>\n<li>Entwickler von zeitkritischen Tasks/Funktionen müssen beachten, dass der Wechsel von nativer Ausführung zu <code>HIGH_PROXY</code>/<code>LOW_PROXY</code> zusätzliche IPC-Latenzen, Pufferkopien und ggf. Partitions-/Privilegienwechsel (User-Mode zu OS-Context) induziert.</li>\n<li><strong>Einschränkung bei Memory Buffern:</strong></li>\n<li>Bei <code>SwCluCProxyGenerationNvM = HIGH_PROXY</code> müssen RAM-Mirror-Puffer entweder in einem shared Memory-Bereich liegen oder durch den SwCluC-Mechanismus explizit kopiert werden; Zeiger-Übergaben über Clustergrenzen hinweg sind bei getrennten Adressräumen (MMU/MPU-Partitionierung) ungültig.</li>\n</ul>"}, {"id": "FIG-25bbaa32b27086f1", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm zur Spezifikation des AUTOSAR BSW-Konfigurationsmetamodells (ECUC Parameter Definition Metamodel gemäß AUTOSAR Generic Structure Template).</li>\n<li><strong>Technischer Zweck:</strong> Definition der Konfigurationsstruktur des BSW-Moduls <code>SwCluC</code> (<em>Software Cluster Connection</em>) zur Steuerung der Codegenerierung von Inter-Cluster-Proxies für Kern-BSW- und Kommunikationsdienste (<em>Operating System</em>, <em>Non-Volatile Memory Manager</em>, <em>Communication</em> und <em>Large Data Communication</em>).</li>\n<li><strong>Funktionale Einordnung:</strong> Ermöglicht die Entkopplung und asymmetrische Verteilung von Software-Clustern (SWCLs) auf einer ECU (z. B. Host-Cluster mit Basistreiber-/BSW-Instanzen vs. separat updatebare Applikations-Cluster). Die Konfiguration legt fest, ob ein Software-Cluster als Service-Konsument (Client), Service-Bereitsteller (Server) oder autark agiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>SwCluC</code> (<code>EcucModuleDef</code>):</strong></li>\n<li>Wurzelelement der Modulkonfigurationsdefinition des Software-Cluster-Connection-Moduls.</li>\n<li><em>Multiplizität:</em> <code>[0..1]</code> (kann je ECU-Konfiguration maximal einmal instanziiert werden; Namensraum <code>(from SwCluC)</code>).</li>\n<li><strong><code>SwCluCProxies</code> (<code>EcucParamConfContainerDef</code>):</strong></li>\n<li>Zentraler Konfigurationscontainer für generelle Proxy-Generierungsparameter.</li>\n<li><em>Beziehung:</em> Komposition (<code>+container</code>, gefüllte Raute) von <code>SwCluC</code> mit strikter Kardinalität <code>[1..1]</code> (Pflichtcontainer).</li>\n<li><strong><code>SwCluCProxyGenerationOs</code> (<code>EcucEnumerationParamDef</code>):</strong></li>\n<li>Steuerungsparameter für OS-Proxy-Artefakte.</li>\n<li><em>Beziehung:</em> Komposition (<code>+parameter</code>) unter <code>SwCluCProxies</code> mit Kardinalität <code>[1..1]</code>.</li>\n<li><em>Literale (<code>EcucEnumerationLiteralDef</code> via <code>+literal</code>, jeweils [0..1] Auswahl):</em></li>\n<li><code>PROXY_DISABLED</code>: Keine Generierung von OS-Proxies im Ziel-Cluster (Cluster nutzt OS direkt lokal oder benötigt keine OS-Dienste über SwCluC).</li>\n<li><code>HIGH_PROXY</code>: Generiert den aufrufenden OS-Proxy (Client-/Caller-Seite) im abhängigen Cluster; fängt OS-Service-Calls ab und leitet sie über den SwCluC-Transport weiter.</li>\n<li><code>LOW_PROXY</code>: Generiert den empfangenden OS-Proxy (Server-/Dispatcher-Seite) im Host-Cluster; nimmt weitergeleitete OS-Calls entgegen und ruft die eigentliche OS-Implementierung auf.</li>\n<li><strong><code>SwCluCProxyGenerationNvM</code> (<code>EcucEnumerationParamDef</code>):</strong></li>\n<li>Steuerungsparameter für NvM-Proxy-Artefakte.</li>\n<li><em>Beziehung:</em> Komposition (<code>+parameter</code>) unter <code>SwCluCProxies</code> mit Kardinalität <code>[1..1]</code>.</li>\n<li><em>Literale (<code>EcucEnumerationLiteralDef</code> via <code>+literal</code>, jeweils [0..1] Auswahl):</em></li>\n<li><code>PROXY_DISABLED</code>: Keine NvM-Proxy-Generierung.</li>\n<li><code>HIGH_PROXY</code>: Generiert den Client-Proxy für NvM-Dienste (z. B. <code>NvM_ReadBlock</code>, <code>NvM_WriteBlock</code>) im Konsumenten-Cluster inklusive IPC-Serialisierung.</li>\n<li><code>LOW_PROXY</code>: Generiert den Dispatcher-Proxy im Host-Cluster, welcher Anfragen an den nativen NvM-Stack durchstellt und Rückmelde-Callbacks handhabt.</li>\n<li><strong><code>SwCluCProxyGenerationCom</code> (<code>EcucEnumerationParamDef</code>):</strong></li>\n<li>Steuerungsparameter für COM-Proxy-Artefakte.</li>\n<li><em>Beziehung:</em> Komposition (<code>+parameter</code>) unter <code>SwCluCProxies</code> mit Kardinalität <code>[1..1]</code>.</li>\n<li><em>Literale (<code>EcucEnumerationLiteralDef</code> via <code>+literal</code>, jeweils [0..1] Auswahl):</em></li>\n<li><code>PROXY_DISABLED</code>: Keine Generierung von COM-Proxies im Ziel-Cluster.</li>\n<li><code>HIGH_PROXY</code>: Generiert den aufrufenden COM-Proxy (Client-Seite) im sendenden/empfangenden Cluster zur Inter-Cluster-Kommunikation über SwCluC.</li>\n<li><code>LOW_PROXY</code>: Generiert den Dispatcher-Proxy für COM im Host-Cluster zur Anbindung an den eigentlichen COM-Stack.</li>\n<li><strong><code>SwCluCProxyGenerationLdCom</code> (<code>EcucEnumerationParamDef</code>):</strong></li>\n<li>Steuerungsparameter für LdCom-Proxy-Artefakte (Large Data Communication).</li>\n<li><em>Beziehung:</em> Komposition (<code>+parameter</code>) unter <code>SwCluCProxies</code> mit Kardinalität <code>[1..1]</code>.</li>\n<li><em>Literale (<code>EcucEnumerationLiteralDef</code> via <code>+literal</code>, jeweils [0..1] Auswahl):</em></li>\n<li><code>PROXY_DISABLED</code>: Keine Generierung von LdCom-Proxies im Ziel-Cluster.</li>\n<li><code>HIGH_PROXY</code>: Generiert den aufrufenden LdCom-Proxy (Client-Seite) zur Übertragung großer Datenmengen über SwCluC.</li>\n<li><code>LOW_PROXY</code>: Generiert den Dispatcher-Proxy für LdCom im Host-Cluster zur Weiterleitung an das LdCom-Modul.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell handelt, bestimmt die Konfiguration den Codegenerator-Pfad sowie den resultierenden Laufzeit-Interaktionsfluss:</p>\n<ol class=\"fig-list\">\n<li><strong>Generierungsphase (Pre-Compile / Build Time):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ist im Cluster A <code>HIGH_PROXY</code> und im Cluster B <code>LOW_PROXY</code> für ein Modul (z. B. NvM) konfiguriert, erzeugt das SwCluC-Generatortool für Cluster A die API-Header/Stubs (<code>High Proxy</code>) und für Cluster B die Dispatcher-Funktionen (<code>Low Proxy</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchroner Request-Pfad (Laufzeit):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>SWC in Cluster A ruft Standard-API auf (z. B. <code>NvM_WriteBlock(...)</code>).</li>\n<li><code>HIGH_PROXY</code> fängt Aufruf ab, serialisiert Argumente (Block-ID, Pufferzeiger/Payload) in ein Inter-Cluster-Nachrichtenformat und triggert den SwCluC-Transport (z. B. Shared Memory, Mailbox-IPC oder Hardware-IPC).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Dispatcher & BSW-Ausführung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>SwCluC-Stack in Cluster B signalisiert Datenverfügbarkeit; <code>LOW_PROXY</code> deserialisiert die Daten und ruft die native BSW-Funktion (<code>NvM_WriteBlock</code>) im lokalen Kontext des Host-Clusters auf.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Asynchrone Callbacks & Job-Terminierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei Abschluss des NvM-Jobs triggert der native Stack den Callback im Host-Cluster.</li>\n<li>Der <code>LOW_PROXY</code> übermittelt den Status (<code>NVM_REQ_OK</code>, <code>NVM_REQ_NOT_OK</code>) über SwCluC zurück an Cluster A, wo der <code>HIGH_PROXY</code> den registrierten Single-Block-/Multi-Block-Callback der anfordernden SWC ausführt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationskonsistenz (ECUC_SwCluC_00036):</strong></li>\n<li>Die Konfiguration muss clusterübergreifend komplementär sein: Konfiguriert ein Applikations-Cluster <code>HIGH_PROXY</code>, <em>muss</em> der bereitstellende Host-Cluster zwingend auf <code>LOW_PROXY</code> für dasselbe Modul parametriert sein. Eine Fehlkonfiguration (<code>HIGH_PROXY</code> ohne korrespondierenden <code>LOW_PROXY</code> oder beidseitig <code>LOW_PROXY</code>) führt zu unaufgelösten Symbolen beim Linken oder deadlocks im IPC-Handshake.</li>\n<li><strong>API-Transparenz für Applikations-Entwickler:</strong></li>\n<li>Durch <code>HIGH_PROXY</code> bleibt die Standard-AUTOSAR-Schnittstelle (<code>Os.h</code>, <code>NvM.h</code>) für SWCs und CDDs im Applikations-Cluster identisch. Es ist keine Anpassung des SWC-Codes erforderlich; die Umleitung auf SwCluC geschieht rein über Include-Pfade und Linker-Reihenfolge.</li>\n<li><strong>Timing & Latenzen:</strong></li>\n<li>Entwickler von zeitkritischen Tasks/Funktionen müssen beachten, dass der Wechsel von nativer Ausführung zu <code>HIGH_PROXY</code>/<code>LOW_PROXY</code> zusätzliche IPC-Latenzen, Pufferkopien und ggf. Partitions-/Privilegienwechsel (User-Mode zu OS-Context) induziert.</li>\n<li><strong>Einschränkung bei Memory Buffern:</strong></li>\n<li>Bei <code>SwCluCProxyGenerationNvM = HIGH_PROXY</code> müssen RAM-Mirror-Puffer entweder in einem shared Memory-Bereich liegen oder durch den SwCluC-Mechanismus explizit kopiert werden; Zeiger-Übergaben über Clustergrenzen hinweg sind bei getrennten Adressräumen (MMU/MPU-Partitionierung) ungültig.</li>\n</ul>"}, {"id": "FIG-3e8c4b17e72e1c98", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm zur Spezifikation des AUTOSAR BSW-Konfigurationsmetamodells (ECUC Parameter Definition Metamodel gemäß AUTOSAR Generic Structure Template).</li>\n<li><strong>Technischer Zweck:</strong> Definition der Konfigurationsstruktur des BSW-Moduls <code>SwCluC</code> (<em>Software Cluster Connection</em>) zur Steuerung der Codegenerierung von Inter-Cluster-Proxies für Kern-BSW- und Kommunikationsdienste (<em>Operating System</em>, <em>Non-Volatile Memory Manager</em>, <em>Communication</em> und <em>Large Data Communication</em>).</li>\n<li><strong>Funktionale Einordnung:</strong> Ermöglicht die Entkopplung und asymmetrische Verteilung von Software-Clustern (SWCLs) auf einer ECU (z. B. Host-Cluster mit Basistreiber-/BSW-Instanzen vs. separat updatebare Applikations-Cluster). Die Konfiguration legt fest, ob ein Software-Cluster als Service-Konsument (Client), Service-Bereitsteller (Server) oder autark agiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>SwCluC</code> (<code>EcucModuleDef</code>):</strong></li>\n<li>Wurzelelement der Modulkonfigurationsdefinition des Software-Cluster-Connection-Moduls.</li>\n<li><em>Multiplizität:</em> <code>[0..1]</code> (kann je ECU-Konfiguration maximal einmal instanziiert werden; Namensraum <code>(from SwCluC)</code>).</li>\n<li><strong><code>SwCluCProxies</code> (<code>EcucParamConfContainerDef</code>):</strong></li>\n<li>Zentraler Konfigurationscontainer für generelle Proxy-Generierungsparameter.</li>\n<li><em>Beziehung:</em> Komposition (<code>+container</code>, gefüllte Raute) von <code>SwCluC</code> mit strikter Kardinalität <code>[1..1]</code> (Pflichtcontainer).</li>\n<li><strong><code>SwCluCProxyGenerationOs</code> (<code>EcucEnumerationParamDef</code>):</strong></li>\n<li>Steuerungsparameter für OS-Proxy-Artefakte.</li>\n<li><em>Beziehung:</em> Komposition (<code>+parameter</code>) unter <code>SwCluCProxies</code> mit Kardinalität <code>[1..1]</code>.</li>\n<li><em>Literale (<code>EcucEnumerationLiteralDef</code> via <code>+literal</code>, jeweils [0..1] Auswahl):</em></li>\n<li><code>PROXY_DISABLED</code>: Keine Generierung von OS-Proxies im Ziel-Cluster (Cluster nutzt OS direkt lokal oder benötigt keine OS-Dienste über SwCluC).</li>\n<li><code>HIGH_PROXY</code>: Generiert den aufrufenden OS-Proxy (Client-/Caller-Seite) im abhängigen Cluster; fängt OS-Service-Calls ab und leitet sie über den SwCluC-Transport weiter.</li>\n<li><code>LOW_PROXY</code>: Generiert den empfangenden OS-Proxy (Server-/Dispatcher-Seite) im Host-Cluster; nimmt weitergeleitete OS-Calls entgegen und ruft die eigentliche OS-Implementierung auf.</li>\n<li><strong><code>SwCluCProxyGenerationNvM</code> (<code>EcucEnumerationParamDef</code>):</strong></li>\n<li>Steuerungsparameter für NvM-Proxy-Artefakte.</li>\n<li><em>Beziehung:</em> Komposition (<code>+parameter</code>) unter <code>SwCluCProxies</code> mit Kardinalität <code>[1..1]</code>.</li>\n<li><em>Literale (<code>EcucEnumerationLiteralDef</code> via <code>+literal</code>, jeweils [0..1] Auswahl):</em></li>\n<li><code>PROXY_DISABLED</code>: Keine NvM-Proxy-Generierung.</li>\n<li><code>HIGH_PROXY</code>: Generiert den Client-Proxy für NvM-Dienste (z. B. <code>NvM_ReadBlock</code>, <code>NvM_WriteBlock</code>) im Konsumenten-Cluster inklusive IPC-Serialisierung.</li>\n<li><code>LOW_PROXY</code>: Generiert den Dispatcher-Proxy im Host-Cluster, welcher Anfragen an den nativen NvM-Stack durchstellt und Rückmelde-Callbacks handhabt.</li>\n<li><strong><code>SwCluCProxyGenerationCom</code> (<code>EcucEnumerationParamDef</code>):</strong></li>\n<li>Steuerungsparameter für COM-Proxy-Artefakte.</li>\n<li><em>Beziehung:</em> Komposition (<code>+parameter</code>) unter <code>SwCluCProxies</code> mit Kardinalität <code>[1..1]</code>.</li>\n<li><em>Literale (<code>EcucEnumerationLiteralDef</code> via <code>+literal</code>, jeweils [0..1] Auswahl):</em></li>\n<li><code>PROXY_DISABLED</code>: Keine Generierung von COM-Proxies im Ziel-Cluster.</li>\n<li><code>HIGH_PROXY</code>: Generiert den aufrufenden COM-Proxy (Client-Seite) im sendenden/empfangenden Cluster zur Inter-Cluster-Kommunikation über SwCluC.</li>\n<li><code>LOW_PROXY</code>: Generiert den Dispatcher-Proxy für COM im Host-Cluster zur Anbindung an den eigentlichen COM-Stack.</li>\n<li><strong><code>SwCluCProxyGenerationLdCom</code> (<code>EcucEnumerationParamDef</code>):</strong></li>\n<li>Steuerungsparameter für LdCom-Proxy-Artefakte (Large Data Communication).</li>\n<li><em>Beziehung:</em> Komposition (<code>+parameter</code>) unter <code>SwCluCProxies</code> mit Kardinalität <code>[1..1]</code>.</li>\n<li><em>Literale (<code>EcucEnumerationLiteralDef</code> via <code>+literal</code>, jeweils [0..1] Auswahl):</em></li>\n<li><code>PROXY_DISABLED</code>: Keine Generierung von LdCom-Proxies im Ziel-Cluster.</li>\n<li><code>HIGH_PROXY</code>: Generiert den aufrufenden LdCom-Proxy (Client-Seite) zur Übertragung großer Datenmengen über SwCluC.</li>\n<li><code>LOW_PROXY</code>: Generiert den Dispatcher-Proxy für LdCom im Host-Cluster zur Weiterleitung an das LdCom-Modul.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell handelt, bestimmt die Konfiguration den Codegenerator-Pfad sowie den resultierenden Laufzeit-Interaktionsfluss:</p>\n<ol class=\"fig-list\">\n<li><strong>Generierungsphase (Pre-Compile / Build Time):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ist im Cluster A <code>HIGH_PROXY</code> und im Cluster B <code>LOW_PROXY</code> für ein Modul (z. B. NvM) konfiguriert, erzeugt das SwCluC-Generatortool für Cluster A die API-Header/Stubs (<code>High Proxy</code>) und für Cluster B die Dispatcher-Funktionen (<code>Low Proxy</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchroner Request-Pfad (Laufzeit):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>SWC in Cluster A ruft Standard-API auf (z. B. <code>NvM_WriteBlock(...)</code>).</li>\n<li><code>HIGH_PROXY</code> fängt Aufruf ab, serialisiert Argumente (Block-ID, Pufferzeiger/Payload) in ein Inter-Cluster-Nachrichtenformat und triggert den SwCluC-Transport (z. B. Shared Memory, Mailbox-IPC oder Hardware-IPC).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Dispatcher & BSW-Ausführung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>SwCluC-Stack in Cluster B signalisiert Datenverfügbarkeit; <code>LOW_PROXY</code> deserialisiert die Daten und ruft die native BSW-Funktion (<code>NvM_WriteBlock</code>) im lokalen Kontext des Host-Clusters auf.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Asynchrone Callbacks & Job-Terminierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei Abschluss des NvM-Jobs triggert der native Stack den Callback im Host-Cluster.</li>\n<li>Der <code>LOW_PROXY</code> übermittelt den Status (<code>NVM_REQ_OK</code>, <code>NVM_REQ_NOT_OK</code>) über SwCluC zurück an Cluster A, wo der <code>HIGH_PROXY</code> den registrierten Single-Block-/Multi-Block-Callback der anfordernden SWC ausführt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationskonsistenz (ECUC_SwCluC_00036):</strong></li>\n<li>Die Konfiguration muss clusterübergreifend komplementär sein: Konfiguriert ein Applikations-Cluster <code>HIGH_PROXY</code>, <em>muss</em> der bereitstellende Host-Cluster zwingend auf <code>LOW_PROXY</code> für dasselbe Modul parametriert sein. Eine Fehlkonfiguration (<code>HIGH_PROXY</code> ohne korrespondierenden <code>LOW_PROXY</code> oder beidseitig <code>LOW_PROXY</code>) führt zu unaufgelösten Symbolen beim Linken oder deadlocks im IPC-Handshake.</li>\n<li><strong>API-Transparenz für Applikations-Entwickler:</strong></li>\n<li>Durch <code>HIGH_PROXY</code> bleibt die Standard-AUTOSAR-Schnittstelle (<code>Os.h</code>, <code>NvM.h</code>) für SWCs und CDDs im Applikations-Cluster identisch. Es ist keine Anpassung des SWC-Codes erforderlich; die Umleitung auf SwCluC geschieht rein über Include-Pfade und Linker-Reihenfolge.</li>\n<li><strong>Timing & Latenzen:</strong></li>\n<li>Entwickler von zeitkritischen Tasks/Funktionen müssen beachten, dass der Wechsel von nativer Ausführung zu <code>HIGH_PROXY</code>/<code>LOW_PROXY</code> zusätzliche IPC-Latenzen, Pufferkopien und ggf. Partitions-/Privilegienwechsel (User-Mode zu OS-Context) induziert.</li>\n<li><strong>Einschränkung bei Memory Buffern:</strong></li>\n<li>Bei <code>SwCluCProxyGenerationNvM = HIGH_PROXY</code> müssen RAM-Mirror-Puffer entweder in einem shared Memory-Bereich liegen oder durch den SwCluC-Mechanismus explizit kopiert werden; Zeiger-Übergaben über Clustergrenzen hinweg sind bei getrennten Adressräumen (MMU/MPU-Partitionierung) ungültig.</li>\n</ul>"}, {"id": "FIG-a35757c24e35de15", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm zur Spezifikation des AUTOSAR BSW-Konfigurationsmetamodells (ECUC Parameter Definition Metamodel gemäß AUTOSAR Generic Structure Template).</li>\n<li><strong>Technischer Zweck:</strong> Definition der Konfigurationsstruktur des BSW-Moduls <code>SwCluC</code> (<em>Software Cluster Connection</em>) zur Steuerung der Codegenerierung von Inter-Cluster-Proxies für Kern-BSW- und Kommunikationsdienste (<em>Operating System</em>, <em>Non-Volatile Memory Manager</em>, <em>Communication</em> und <em>Large Data Communication</em>).</li>\n<li><strong>Funktionale Einordnung:</strong> Ermöglicht die Entkopplung und asymmetrische Verteilung von Software-Clustern (SWCLs) auf einer ECU (z. B. Host-Cluster mit Basistreiber-/BSW-Instanzen vs. separat updatebare Applikations-Cluster). Die Konfiguration legt fest, ob ein Software-Cluster als Service-Konsument (Client), Service-Bereitsteller (Server) oder autark agiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>SwCluC</code> (<code>EcucModuleDef</code>):</strong></li>\n<li>Wurzelelement der Modulkonfigurationsdefinition des Software-Cluster-Connection-Moduls.</li>\n<li><em>Multiplizität:</em> <code>[0..1]</code> (kann je ECU-Konfiguration maximal einmal instanziiert werden; Namensraum <code>(from SwCluC)</code>).</li>\n<li><strong><code>SwCluCProxies</code> (<code>EcucParamConfContainerDef</code>):</strong></li>\n<li>Zentraler Konfigurationscontainer für generelle Proxy-Generierungsparameter.</li>\n<li><em>Beziehung:</em> Komposition (<code>+container</code>, gefüllte Raute) von <code>SwCluC</code> mit strikter Kardinalität <code>[1..1]</code> (Pflichtcontainer).</li>\n<li><strong><code>SwCluCProxyGenerationOs</code> (<code>EcucEnumerationParamDef</code>):</strong></li>\n<li>Steuerungsparameter für OS-Proxy-Artefakte.</li>\n<li><em>Beziehung:</em> Komposition (<code>+parameter</code>) unter <code>SwCluCProxies</code> mit Kardinalität <code>[1..1]</code>.</li>\n<li><em>Literale (<code>EcucEnumerationLiteralDef</code> via <code>+literal</code>, jeweils [0..1] Auswahl):</em></li>\n<li><code>PROXY_DISABLED</code>: Keine Generierung von OS-Proxies im Ziel-Cluster (Cluster nutzt OS direkt lokal oder benötigt keine OS-Dienste über SwCluC).</li>\n<li><code>HIGH_PROXY</code>: Generiert den aufrufenden OS-Proxy (Client-/Caller-Seite) im abhängigen Cluster; fängt OS-Service-Calls ab und leitet sie über den SwCluC-Transport weiter.</li>\n<li><code>LOW_PROXY</code>: Generiert den empfangenden OS-Proxy (Server-/Dispatcher-Seite) im Host-Cluster; nimmt weitergeleitete OS-Calls entgegen und ruft die eigentliche OS-Implementierung auf.</li>\n<li><strong><code>SwCluCProxyGenerationNvM</code> (<code>EcucEnumerationParamDef</code>):</strong></li>\n<li>Steuerungsparameter für NvM-Proxy-Artefakte.</li>\n<li><em>Beziehung:</em> Komposition (<code>+parameter</code>) unter <code>SwCluCProxies</code> mit Kardinalität <code>[1..1]</code>.</li>\n<li><em>Literale (<code>EcucEnumerationLiteralDef</code> via <code>+literal</code>, jeweils [0..1] Auswahl):</em></li>\n<li><code>PROXY_DISABLED</code>: Keine NvM-Proxy-Generierung.</li>\n<li><code>HIGH_PROXY</code>: Generiert den Client-Proxy für NvM-Dienste (z. B. <code>NvM_ReadBlock</code>, <code>NvM_WriteBlock</code>) im Konsumenten-Cluster inklusive IPC-Serialisierung.</li>\n<li><code>LOW_PROXY</code>: Generiert den Dispatcher-Proxy im Host-Cluster, welcher Anfragen an den nativen NvM-Stack durchstellt und Rückmelde-Callbacks handhabt.</li>\n<li><strong><code>SwCluCProxyGenerationCom</code> (<code>EcucEnumerationParamDef</code>):</strong></li>\n<li>Steuerungsparameter für COM-Proxy-Artefakte.</li>\n<li><em>Beziehung:</em> Komposition (<code>+parameter</code>) unter <code>SwCluCProxies</code> mit Kardinalität <code>[1..1]</code>.</li>\n<li><em>Literale (<code>EcucEnumerationLiteralDef</code> via <code>+literal</code>, jeweils [0..1] Auswahl):</em></li>\n<li><code>PROXY_DISABLED</code>: Keine Generierung von COM-Proxies im Ziel-Cluster.</li>\n<li><code>HIGH_PROXY</code>: Generiert den aufrufenden COM-Proxy (Client-Seite) im sendenden/empfangenden Cluster zur Inter-Cluster-Kommunikation über SwCluC.</li>\n<li><code>LOW_PROXY</code>: Generiert den Dispatcher-Proxy für COM im Host-Cluster zur Anbindung an den eigentlichen COM-Stack.</li>\n<li><strong><code>SwCluCProxyGenerationLdCom</code> (<code>EcucEnumerationParamDef</code>):</strong></li>\n<li>Steuerungsparameter für LdCom-Proxy-Artefakte (Large Data Communication).</li>\n<li><em>Beziehung:</em> Komposition (<code>+parameter</code>) unter <code>SwCluCProxies</code> mit Kardinalität <code>[1..1]</code>.</li>\n<li><em>Literale (<code>EcucEnumerationLiteralDef</code> via <code>+literal</code>, jeweils [0..1] Auswahl):</em></li>\n<li><code>PROXY_DISABLED</code>: Keine Generierung von LdCom-Proxies im Ziel-Cluster.</li>\n<li><code>HIGH_PROXY</code>: Generiert den aufrufenden LdCom-Proxy (Client-Seite) zur Übertragung großer Datenmengen über SwCluC.</li>\n<li><code>LOW_PROXY</code>: Generiert den Dispatcher-Proxy für LdCom im Host-Cluster zur Weiterleitung an das LdCom-Modul.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell handelt, bestimmt die Konfiguration den Codegenerator-Pfad sowie den resultierenden Laufzeit-Interaktionsfluss:</p>\n<ol class=\"fig-list\">\n<li><strong>Generierungsphase (Pre-Compile / Build Time):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ist im Cluster A <code>HIGH_PROXY</code> und im Cluster B <code>LOW_PROXY</code> für ein Modul (z. B. NvM) konfiguriert, erzeugt das SwCluC-Generatortool für Cluster A die API-Header/Stubs (<code>High Proxy</code>) und für Cluster B die Dispatcher-Funktionen (<code>Low Proxy</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchroner Request-Pfad (Laufzeit):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>SWC in Cluster A ruft Standard-API auf (z. B. <code>NvM_WriteBlock(...)</code>).</li>\n<li><code>HIGH_PROXY</code> fängt Aufruf ab, serialisiert Argumente (Block-ID, Pufferzeiger/Payload) in ein Inter-Cluster-Nachrichtenformat und triggert den SwCluC-Transport (z. B. Shared Memory, Mailbox-IPC oder Hardware-IPC).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Dispatcher & BSW-Ausführung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>SwCluC-Stack in Cluster B signalisiert Datenverfügbarkeit; <code>LOW_PROXY</code> deserialisiert die Daten und ruft die native BSW-Funktion (<code>NvM_WriteBlock</code>) im lokalen Kontext des Host-Clusters auf.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Asynchrone Callbacks & Job-Terminierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei Abschluss des NvM-Jobs triggert der native Stack den Callback im Host-Cluster.</li>\n<li>Der <code>LOW_PROXY</code> übermittelt den Status (<code>NVM_REQ_OK</code>, <code>NVM_REQ_NOT_OK</code>) über SwCluC zurück an Cluster A, wo der <code>HIGH_PROXY</code> den registrierten Single-Block-/Multi-Block-Callback der anfordernden SWC ausführt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationskonsistenz (ECUC_SwCluC_00036):</strong></li>\n<li>Die Konfiguration muss clusterübergreifend komplementär sein: Konfiguriert ein Applikations-Cluster <code>HIGH_PROXY</code>, <em>muss</em> der bereitstellende Host-Cluster zwingend auf <code>LOW_PROXY</code> für dasselbe Modul parametriert sein. Eine Fehlkonfiguration (<code>HIGH_PROXY</code> ohne korrespondierenden <code>LOW_PROXY</code> oder beidseitig <code>LOW_PROXY</code>) führt zu unaufgelösten Symbolen beim Linken oder deadlocks im IPC-Handshake.</li>\n<li><strong>API-Transparenz für Applikations-Entwickler:</strong></li>\n<li>Durch <code>HIGH_PROXY</code> bleibt die Standard-AUTOSAR-Schnittstelle (<code>Os.h</code>, <code>NvM.h</code>) für SWCs und CDDs im Applikations-Cluster identisch. Es ist keine Anpassung des SWC-Codes erforderlich; die Umleitung auf SwCluC geschieht rein über Include-Pfade und Linker-Reihenfolge.</li>\n<li><strong>Timing & Latenzen:</strong></li>\n<li>Entwickler von zeitkritischen Tasks/Funktionen müssen beachten, dass der Wechsel von nativer Ausführung zu <code>HIGH_PROXY</code>/<code>LOW_PROXY</code> zusätzliche IPC-Latenzen, Pufferkopien und ggf. Partitions-/Privilegienwechsel (User-Mode zu OS-Context) induziert.</li>\n<li><strong>Einschränkung bei Memory Buffern:</strong></li>\n<li>Bei <code>SwCluCProxyGenerationNvM = HIGH_PROXY</code> müssen RAM-Mirror-Puffer entweder in einem shared Memory-Bereich liegen oder durch den SwCluC-Mechanismus explizit kopiert werden; Zeiger-Übergaben über Clustergrenzen hinweg sind bei getrennten Adressräumen (MMU/MPU-Partitionierung) ungültig.</li>\n</ul>"}, {"id": "FIG-4827cca376e71e42", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm zur Spezifikation des AUTOSAR BSW-Konfigurationsmetamodells (ECUC Parameter Definition Metamodel gemäß AUTOSAR Generic Structure Template).</li>\n<li><strong>Technischer Zweck:</strong> Definition der Konfigurationsstruktur des BSW-Moduls <code>SwCluC</code> (<em>Software Cluster Connection</em>) zur Steuerung der Codegenerierung von Inter-Cluster-Proxies für Kern-BSW- und Kommunikationsdienste (<em>Operating System</em>, <em>Non-Volatile Memory Manager</em>, <em>Communication</em> und <em>Large Data Communication</em>).</li>\n<li><strong>Funktionale Einordnung:</strong> Ermöglicht die Entkopplung und asymmetrische Verteilung von Software-Clustern (SWCLs) auf einer ECU (z. B. Host-Cluster mit Basistreiber-/BSW-Instanzen vs. separat updatebare Applikations-Cluster). Die Konfiguration legt fest, ob ein Software-Cluster als Service-Konsument (Client), Service-Bereitsteller (Server) oder autark agiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>SwCluC</code> (<code>EcucModuleDef</code>):</strong></li>\n<li>Wurzelelement der Modulkonfigurationsdefinition des Software-Cluster-Connection-Moduls.</li>\n<li><em>Multiplizität:</em> <code>[0..1]</code> (kann je ECU-Konfiguration maximal einmal instanziiert werden; Namensraum <code>(from SwCluC)</code>).</li>\n<li><strong><code>SwCluCProxies</code> (<code>EcucParamConfContainerDef</code>):</strong></li>\n<li>Zentraler Konfigurationscontainer für generelle Proxy-Generierungsparameter.</li>\n<li><em>Beziehung:</em> Komposition (<code>+container</code>, gefüllte Raute) von <code>SwCluC</code> mit strikter Kardinalität <code>[1..1]</code> (Pflichtcontainer).</li>\n<li><strong><code>SwCluCProxyGenerationOs</code> (<code>EcucEnumerationParamDef</code>):</strong></li>\n<li>Steuerungsparameter für OS-Proxy-Artefakte.</li>\n<li><em>Beziehung:</em> Komposition (<code>+parameter</code>) unter <code>SwCluCProxies</code> mit Kardinalität <code>[1..1]</code>.</li>\n<li><em>Literale (<code>EcucEnumerationLiteralDef</code> via <code>+literal</code>, jeweils [0..1] Auswahl):</em></li>\n<li><code>PROXY_DISABLED</code>: Keine Generierung von OS-Proxies im Ziel-Cluster (Cluster nutzt OS direkt lokal oder benötigt keine OS-Dienste über SwCluC).</li>\n<li><code>HIGH_PROXY</code>: Generiert den aufrufenden OS-Proxy (Client-/Caller-Seite) im abhängigen Cluster; fängt OS-Service-Calls ab und leitet sie über den SwCluC-Transport weiter.</li>\n<li><code>LOW_PROXY</code>: Generiert den empfangenden OS-Proxy (Server-/Dispatcher-Seite) im Host-Cluster; nimmt weitergeleitete OS-Calls entgegen und ruft die eigentliche OS-Implementierung auf.</li>\n<li><strong><code>SwCluCProxyGenerationNvM</code> (<code>EcucEnumerationParamDef</code>):</strong></li>\n<li>Steuerungsparameter für NvM-Proxy-Artefakte.</li>\n<li><em>Beziehung:</em> Komposition (<code>+parameter</code>) unter <code>SwCluCProxies</code> mit Kardinalität <code>[1..1]</code>.</li>\n<li><em>Literale (<code>EcucEnumerationLiteralDef</code> via <code>+literal</code>, jeweils [0..1] Auswahl):</em></li>\n<li><code>PROXY_DISABLED</code>: Keine NvM-Proxy-Generierung.</li>\n<li><code>HIGH_PROXY</code>: Generiert den Client-Proxy für NvM-Dienste (z. B. <code>NvM_ReadBlock</code>, <code>NvM_WriteBlock</code>) im Konsumenten-Cluster inklusive IPC-Serialisierung.</li>\n<li><code>LOW_PROXY</code>: Generiert den Dispatcher-Proxy im Host-Cluster, welcher Anfragen an den nativen NvM-Stack durchstellt und Rückmelde-Callbacks handhabt.</li>\n<li><strong><code>SwCluCProxyGenerationCom</code> (<code>EcucEnumerationParamDef</code>):</strong></li>\n<li>Steuerungsparameter für COM-Proxy-Artefakte.</li>\n<li><em>Beziehung:</em> Komposition (<code>+parameter</code>) unter <code>SwCluCProxies</code> mit Kardinalität <code>[1..1]</code>.</li>\n<li><em>Literale (<code>EcucEnumerationLiteralDef</code> via <code>+literal</code>, jeweils [0..1] Auswahl):</em></li>\n<li><code>PROXY_DISABLED</code>: Keine Generierung von COM-Proxies im Ziel-Cluster.</li>\n<li><code>HIGH_PROXY</code>: Generiert den aufrufenden COM-Proxy (Client-Seite) im sendenden/empfangenden Cluster zur Inter-Cluster-Kommunikation über SwCluC.</li>\n<li><code>LOW_PROXY</code>: Generiert den Dispatcher-Proxy für COM im Host-Cluster zur Anbindung an den eigentlichen COM-Stack.</li>\n<li><strong><code>SwCluCProxyGenerationLdCom</code> (<code>EcucEnumerationParamDef</code>):</strong></li>\n<li>Steuerungsparameter für LdCom-Proxy-Artefakte (Large Data Communication).</li>\n<li><em>Beziehung:</em> Komposition (<code>+parameter</code>) unter <code>SwCluCProxies</code> mit Kardinalität <code>[1..1]</code>.</li>\n<li><em>Literale (<code>EcucEnumerationLiteralDef</code> via <code>+literal</code>, jeweils [0..1] Auswahl):</em></li>\n<li><code>PROXY_DISABLED</code>: Keine Generierung von LdCom-Proxies im Ziel-Cluster.</li>\n<li><code>HIGH_PROXY</code>: Generiert den aufrufenden LdCom-Proxy (Client-Seite) zur Übertragung großer Datenmengen über SwCluC.</li>\n<li><code>LOW_PROXY</code>: Generiert den Dispatcher-Proxy für LdCom im Host-Cluster zur Weiterleitung an das LdCom-Modul.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell handelt, bestimmt die Konfiguration den Codegenerator-Pfad sowie den resultierenden Laufzeit-Interaktionsfluss:</p>\n<ol class=\"fig-list\">\n<li><strong>Generierungsphase (Pre-Compile / Build Time):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ist im Cluster A <code>HIGH_PROXY</code> und im Cluster B <code>LOW_PROXY</code> für ein Modul (z. B. NvM) konfiguriert, erzeugt das SwCluC-Generatortool für Cluster A die API-Header/Stubs (<code>High Proxy</code>) und für Cluster B die Dispatcher-Funktionen (<code>Low Proxy</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchroner Request-Pfad (Laufzeit):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>SWC in Cluster A ruft Standard-API auf (z. B. <code>NvM_WriteBlock(...)</code>).</li>\n<li><code>HIGH_PROXY</code> fängt Aufruf ab, serialisiert Argumente (Block-ID, Pufferzeiger/Payload) in ein Inter-Cluster-Nachrichtenformat und triggert den SwCluC-Transport (z. B. Shared Memory, Mailbox-IPC oder Hardware-IPC).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Dispatcher & BSW-Ausführung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>SwCluC-Stack in Cluster B signalisiert Datenverfügbarkeit; <code>LOW_PROXY</code> deserialisiert die Daten und ruft die native BSW-Funktion (<code>NvM_WriteBlock</code>) im lokalen Kontext des Host-Clusters auf.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Asynchrone Callbacks & Job-Terminierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei Abschluss des NvM-Jobs triggert der native Stack den Callback im Host-Cluster.</li>\n<li>Der <code>LOW_PROXY</code> übermittelt den Status (<code>NVM_REQ_OK</code>, <code>NVM_REQ_NOT_OK</code>) über SwCluC zurück an Cluster A, wo der <code>HIGH_PROXY</code> den registrierten Single-Block-/Multi-Block-Callback der anfordernden SWC ausführt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationskonsistenz (ECUC_SwCluC_00036):</strong></li>\n<li>Die Konfiguration muss clusterübergreifend komplementär sein: Konfiguriert ein Applikations-Cluster <code>HIGH_PROXY</code>, <em>muss</em> der bereitstellende Host-Cluster zwingend auf <code>LOW_PROXY</code> für dasselbe Modul parametriert sein. Eine Fehlkonfiguration (<code>HIGH_PROXY</code> ohne korrespondierenden <code>LOW_PROXY</code> oder beidseitig <code>LOW_PROXY</code>) führt zu unaufgelösten Symbolen beim Linken oder deadlocks im IPC-Handshake.</li>\n<li><strong>API-Transparenz für Applikations-Entwickler:</strong></li>\n<li>Durch <code>HIGH_PROXY</code> bleibt die Standard-AUTOSAR-Schnittstelle (<code>Os.h</code>, <code>NvM.h</code>) für SWCs und CDDs im Applikations-Cluster identisch. Es ist keine Anpassung des SWC-Codes erforderlich; die Umleitung auf SwCluC geschieht rein über Include-Pfade und Linker-Reihenfolge.</li>\n<li><strong>Timing & Latenzen:</strong></li>\n<li>Entwickler von zeitkritischen Tasks/Funktionen müssen beachten, dass der Wechsel von nativer Ausführung zu <code>HIGH_PROXY</code>/<code>LOW_PROXY</code> zusätzliche IPC-Latenzen, Pufferkopien und ggf. Partitions-/Privilegienwechsel (User-Mode zu OS-Context) induziert.</li>\n<li><strong>Einschränkung bei Memory Buffern:</strong></li>\n<li>Bei <code>SwCluCProxyGenerationNvM = HIGH_PROXY</code> müssen RAM-Mirror-Puffer entweder in einem shared Memory-Bereich liegen oder durch den SwCluC-Mechanismus explizit kopiert werden; Zeiger-Übergaben über Clustergrenzen hinweg sind bei getrennten Adressräumen (MMU/MPU-Partitionierung) ungültig.</li>\n</ul>"}, {"id": "FIG-bf9e194fcbf757a7", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm zur Spezifikation des AUTOSAR BSW-Konfigurationsmetamodells (ECUC Parameter Definition Metamodel gemäß AUTOSAR Generic Structure Template).</li>\n<li><strong>Technischer Zweck:</strong> Definition der Konfigurationsstruktur des BSW-Moduls <code>SwCluC</code> (<em>Software Cluster Connection</em>) zur Steuerung der Codegenerierung von Inter-Cluster-Proxies für Kern-BSW- und Kommunikationsdienste (<em>Operating System</em>, <em>Non-Volatile Memory Manager</em> und <em>Communication</em>).</li>\n<li><strong>Funktionale Einordnung:</strong> Ermöglicht die Entkopplung und asymmetrische Verteilung von Software-Clustern (SWCLs) auf einer ECU (z. B. Host-Cluster mit Basistreiber-/BSW-Instanzen vs. separat updatebare Applikations-Cluster). Die Konfiguration legt fest, ob ein Software-Cluster als Service-Konsument (Client), Service-Bereitsteller (Server) oder autark agiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>SwCluC</code> (<code>EcucModuleDef</code>):</strong></li>\n<li>Wurzelelement der Modulkonfigurationsdefinition des Software-Cluster-Connection-Moduls.</li>\n<li><em>Multiplizität:</em> <code>[0..1]</code> (kann je ECU-Konfiguration maximal einmal instanziiert werden; Namensraum <code>(from SwCluC)</code>).</li>\n<li><strong><code>SwCluCProxies</code> (<code>EcucParamConfContainerDef</code>):</strong></li>\n<li>Zentraler Konfigurationscontainer für generelle Proxy-Generierungsparameter.</li>\n<li><em>Beziehung:</em> Komposition (<code>+container</code>, gefüllte Raute) von <code>SwCluC</code> mit strikter Kardinalität <code>[1..1]</code> (Pflichtcontainer).</li>\n<li><strong><code>SwCluCProxyGenerationOs</code> (<code>EcucEnumerationParamDef</code>):</strong></li>\n<li>Steuerungsparameter für OS-Proxy-Artefakte.</li>\n<li><em>Beziehung:</em> Komposition (<code>+parameter</code>) unter <code>SwCluCProxies</code> mit Kardinalität <code>[1..1]</code>.</li>\n<li><em>Literale (<code>EcucEnumerationLiteralDef</code> via <code>+literal</code>, jeweils [0..1] Auswahl):</em></li>\n<li><code>PROXY_DISABLED</code>: Keine Generierung von OS-Proxies im Ziel-Cluster (Cluster nutzt OS direkt lokal oder benötigt keine OS-Dienste über SwCluC).</li>\n<li><code>HIGH_PROXY</code>: Generiert den aufrufenden OS-Proxy (Client-/Caller-Seite) im abhängigen Cluster; fängt OS-Service-Calls ab und leitet sie über den SwCluC-Transport weiter.</li>\n<li><code>LOW_PROXY</code>: Generiert den empfangenden OS-Proxy (Server-/Dispatcher-Seite) im Host-Cluster; nimmt weitergeleitete OS-Calls entgegen und ruft die eigentliche OS-Implementierung auf.</li>\n<li><strong><code>SwCluCProxyGenerationNvM</code> (<code>EcucEnumerationParamDef</code>):</strong></li>\n<li>Steuerungsparameter für NvM-Proxy-Artefakte.</li>\n<li><em>Beziehung:</em> Komposition (<code>+parameter</code>) unter <code>SwCluCProxies</code> mit Kardinalität <code>[1..1]</code>.</li>\n<li><em>Literale (<code>EcucEnumerationLiteralDef</code> via <code>+literal</code>, jeweils [0..1] Auswahl):</em></li>\n<li><code>PROXY_DISABLED</code>: Keine NvM-Proxy-Generierung.</li>\n<li><code>HIGH_PROXY</code>: Generiert den Client-Proxy für NvM-Dienste (z. B. <code>NvM_ReadBlock</code>, <code>NvM_WriteBlock</code>) im Konsumenten-Cluster inklusive IPC-Serialisierung.</li>\n<li><code>LOW_PROXY</code>: Generiert den Dispatcher-Proxy im Host-Cluster, welcher Anfragen an den nativen NvM-Stack durchstellt und Rückmelde-Callbacks handhabt.</li>\n<li><strong><code>SwCluCProxyGenerationCom</code> (<code>EcucEnumerationParamDef</code>):</strong></li>\n<li>Steuerungsparameter für COM-Proxy-Artefakte.</li>\n<li><em>Beziehung:</em> Komposition (<code>+parameter</code>) unter <code>SwCluCProxies</code> mit Kardinalität <code>[1..1]</code>.</li>\n<li><em>Literale (<code>EcucEnumerationLiteralDef</code> via <code>+literal</code>, jeweils [0..1] Auswahl):</em></li>\n<li><code>PROXY_DISABLED</code>: Keine Generierung von COM-Proxies im Ziel-Cluster.</li>\n<li><code>HIGH_PROXY</code>: Generiert den aufrufenden COM-Proxy (Client-Seite) im sendenden/empfangenden Cluster zur Inter-Cluster-Kommunikation über SwCluC.</li>\n<li><code>LOW_PROXY</code>: Generiert den Dispatcher-Proxy für COM im Host-Cluster zur Anbindung an den eigentlichen COM-Stack.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell handelt, bestimmt die Konfiguration den Codegenerator-Pfad sowie den resultierenden Laufzeit-Interaktionsfluss:</p>\n<ol class=\"fig-list\">\n<li><strong>Generierungsphase (Pre-Compile / Build Time):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ist im Cluster A <code>HIGH_PROXY</code> und im Cluster B <code>LOW_PROXY</code> für ein Modul (z. B. NvM) konfiguriert, erzeugt das SwCluC-Generatortool für Cluster A die API-Header/Stubs (<code>High Proxy</code>) und für Cluster B die Dispatcher-Funktionen (<code>Low Proxy</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchroner Request-Pfad (Laufzeit):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>SWC in Cluster A ruft Standard-API auf (z. B. <code>NvM_WriteBlock(...)</code>).</li>\n<li><code>HIGH_PROXY</code> fängt Aufruf ab, serialisiert Argumente (Block-ID, Pufferzeiger/Payload) in ein Inter-Cluster-Nachrichtenformat und triggert den SwCluC-Transport (z. B. Shared Memory, Mailbox-IPC oder Hardware-IPC).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Dispatcher & BSW-Ausführung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>SwCluC-Stack in Cluster B signalisiert Datenverfügbarkeit; <code>LOW_PROXY</code> deserialisiert die Daten und ruft die native BSW-Funktion (<code>NvM_WriteBlock</code>) im lokalen Kontext des Host-Clusters auf.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Asynchrone Callbacks & Job-Terminierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei Abschluss des NvM-Jobs triggert der native Stack den Callback im Host-Cluster.</li>\n<li>Der <code>LOW_PROXY</code> übermittelt den Status (<code>NVM_REQ_OK</code>, <code>NVM_REQ_NOT_OK</code>) über SwCluC zurück an Cluster A, wo der <code>HIGH_PROXY</code> den registrierten Single-Block-/Multi-Block-Callback der anfordernden SWC ausführt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationskonsistenz (ECUC_SwCluC_00036):</strong></li>\n<li>Die Konfiguration muss clusterübergreifend komplementär sein: Konfiguriert ein Applikations-Cluster <code>HIGH_PROXY</code>, <em>muss</em> der bereitstellende Host-Cluster zwingend auf <code>LOW_PROXY</code> für dasselbe Modul parametriert sein. Eine Fehlkonfiguration (<code>HIGH_PROXY</code> ohne korrespondierenden <code>LOW_PROXY</code> oder beidseitig <code>LOW_PROXY</code>) führt zu unaufgelösten Symbolen beim Linken oder deadlocks im IPC-Handshake.</li>\n<li><strong>API-Transparenz für Applikations-Entwickler:</strong></li>\n<li>Durch <code>HIGH_PROXY</code> bleibt die Standard-AUTOSAR-Schnittstelle (<code>Os.h</code>, <code>NvM.h</code>) für SWCs und CDDs im Applikations-Cluster identisch. Es ist keine Anpassung des SWC-Codes erforderlich; die Umleitung auf SwCluC geschieht rein über Include-Pfade und Linker-Reihenfolge.</li>\n<li><strong>Timing & Latenzen:</strong></li>\n<li>Entwickler von zeitkritischen Tasks/Funktionen müssen beachten, dass der Wechsel von nativer Ausführung zu <code>HIGH_PROXY</code>/<code>LOW_PROXY</code> zusätzliche IPC-Latenzen, Pufferkopien und ggf. Partitions-/Privilegienwechsel (User-Mode zu OS-Context) induziert.</li>\n<li><strong>Einschränkung bei Memory Buffern:</strong></li>\n<li>Bei <code>SwCluCProxyGenerationNvM = HIGH_PROXY</code> müssen RAM-Mirror-Puffer entweder in einem shared Memory-Bereich liegen oder durch den SwCluC-Mechanismus explizit kopiert werden; Zeiger-Übergaben über Clustergrenzen hinweg sind bei getrennten Adressräumen (MMU/MPU-Partitionierung) ungültig.</li>\n</ul>"}], "trans": [{"from": "FIG-d850fa0129218c46", "to": "FIG-25bbaa32b27086f1", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>SwCluCProxies</code>: Neuer Konfigurationsparameter <code>SwCluCProxyGenerationCom</code> (<code>EcucEnumerationParamDef</code>, Multiplizität <code>[1..1]</code>) mit Beziehung <code>+parameter</code> hinzugefügt.</li>\n<li><code>SwCluCProxyGenerationCom</code>: Literale <code>PROXY_DISABLED</code>, <code>HIGH_PROXY</code> und <code>LOW_PROXY</code> (<code>EcucEnumerationLiteralDef</code>) mit Beziehung <code>+literal</code> hinzugefügt.</li>\n<li><code>SwCluCProxies</code>: Neuer Konfigurationsparameter <code>SwCluCProxyGenerationLdCom</code> (<code>EcucEnumerationParamDef</code>, Multiplizität <code>[1..1]</code>) mit Beziehung <code>+parameter</code> hinzugefügt.</li>\n<li><code>SwCluCProxyGenerationLdCom</code>: Literale <code>PROXY_DISABLED</code>, <code>HIGH_PROXY</code> und <code>LOW_PROXY</code> (<code>EcucEnumerationLiteralDef</code>) mit Beziehung <code>+literal</code> hinzugefügt.</li>\n</ul>"}, {"from": "FIG-25bbaa32b27086f1", "to": "FIG-3e8c4b17e72e1c98", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-3e8c4b17e72e1c98", "to": "FIG-a35757c24e35de15", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-a35757c24e35de15", "to": "FIG-4827cca376e71e42", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>SwCluC</code>: Die Beschriftung im Kopf des Klassenkastens wurde von <code>SwCluC: EcucModuleDef</code> auf zwei Zeilen umbrochen (<code>SwCluC:</code> / <code>EcucModuleDef</code>).</li>\n</ul>"}, {"from": "FIG-4827cca376e71e42", "to": "FIG-bf9e194fcbf757a7", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>SwCluCProxyGenerationLdCom</code>: Konfigurationsparameter (<code>EcucEnumerationParamDef</code>, Multiplizität <code>[1..1]</code>) samt Beziehung <code>+parameter</code> zu <code>SwCluCProxies</code> entfernt.</li>\n<li><code>SwCluCProxyGenerationLdCom</code>: Literale <code>PROXY_DISABLED</code>, <code>HIGH_PROXY</code> und <code>LOW_PROXY</code> (<code>EcucEnumerationLiteralDef</code>) samt <code>+literal</code>-Beziehungen entfernt.</li>\n</ul>"}]};
